import requests
import unicodedata

def task_func(username):
    # If username is empty, return an empty dictionary
    if not username:
        return {}

    # Construct the URL using the provided username
    url = "https://api.github.com/users/" + username

    # Make a GET request to the URL
    response = requests.get(url)

    # Raise an error for any unsuccessful HTTP status codes
    response.raise_for_status()

    # Get the JSON data from the API response
    data = response.json()

    # Normalize the 'name' field if it exists and is a string
    if 'name' in data and isinstance(data['name'], str):
        # Normalize the string to its decomposed form (NFKD)
        normalized = unicodedata.normalize('NFKD', data['name'])
        # Remove any non-ASCII characters by encoding to ASCII and decoding back using UTF-8
        normalized = normalized.encode('ASCII', 'ignore').decode('utf-8')
        data['name'] = normalized

    return data

